t.script:
//
(function () {
    'use strict';

    // ── DOM refs ──────────────────────────────────────────────────────────────────
    var bar         = document.getElementById('cfg_bar');
    var frame       = document.getElementById('cfg_frame');
    var loading     = document.getElementById('cfg_loading');
    var loadingMsg  = document.getElementById('cfg_loading_msg');
    var statusEl    = document.getElementById('cfg_status');
    var styleCtrl   = document.getElementById('cfg_style');
    var vibeCtrl    = document.getElementById('cfg_vibe');
    var layoutCtrl  = document.getElementById('cfg_layout');

    // ── Current selection (from URL params) ──────────────────────────────────────
    var p = new URLSearchParams(location.search);
    var curVibe   = p.get('vibe')   || 'clean';
    var curLayout = p.get('layout') || 'minimalist';
    var curStyle  = p.get('style')  || '';

    // Pre-select controls to match URL state.
    if (curStyle)  styleCtrl.value  = curStyle;
    vibeCtrl.value   = curVibe;
    layoutCtrl.value = curLayout;


    // ── JSON-RPC helper (CSRF not required for Content-Type: application/json) ────
    function jsonRpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1, params: params }),
        }).then(function (r) { return r.json(); }).then(function (d) { return d.result; });
    }

    // ── Read per-style design tokens from the <option> element's dataset ─────────
    // Mirrors CURATED_STYLES in configurator.js.  Falls back to safe defaults
    // when an unknown style id is passed (defensive).
    function readStyleTokens(styleId) {
        var opt = styleCtrl.querySelector('option[value="' + styleId + '"]');
        var d = (opt && opt.dataset) || {};
        return {
            fontHead : d.fontHead || 'Inter Tight',
            fontBody : d.fontBody || 'Inter',
            radius   : d.radius   || '0.5rem',
        };
    }

    // ── Build iframe srcdoc ───────────────────────────────────────────────────────
    // Copies every stylesheet <link> from the current document into the iframe so
    // the preview uses the exact same compiled CSS bundle (including the current
    // palette's custom properties).  A small inline style suppresses any residual
    // <configuratorheader>/<configuratorfooter> elements that might slip through.
    function buildSrcdoc(html) {
        var links = Array.prototype.slice
            .call(document.querySelectorAll('link[rel="stylesheet"]'))
            .map(function (l) { return '<link rel="stylesheet" href="' + l.href + '">'; })
            .join('\n');
        return '<!DOCTYPE html><html lang="en"><head>' +
            '<meta charset="utf-8">' +
            '<style>body{margin:0}' +
            'configuratorheader,configuratorfooter{display:none!important}' +
            /* Prevent navigation: neutralise every link and button in the preview. */
            'a[href],button,input[type="submit"],input[type="button"],[role="button"]{pointer-events:none!important}' +
            'header#top{background:transparent!important}' +
            'header#top .navbar,header#top nav{--o-cc-bg:inherit;--o-cc-text:inherit;--nav-link-color:var(--o-cc-text);--navbar-color:inherit}' +
            '</style>' +
            links +
            '</head><body class="website o_cc1">' + html + '</body></html>';
    }

    // ── Status helpers ────────────────────────────────────────────────────────────
    function setLoading(msg) {
        loadingMsg.textContent = msg || 'Loading…';
        loading.style.display  = 'flex';
        statusEl.textContent   = '';
    }
    function clearLoading(statusMsg) {
        loading.style.display = 'none';
        statusEl.textContent  = statusMsg || '';
    }

    // ── Load and render the current vibe + layout preview ─────────────────────────
    // Calls get_layout_previews (same endpoint as the configurator) with the
    // selected vibe and no industry (default images).  The endpoint returns an
    // object keyed by layoutId; we pick the one we need and inject it as srcdoc.
    function loadPreview() {
        setLoading('Loading…');
        jsonRpc('/website/configurator/get_layout_previews', {
            vibe: curVibe,
            industry_id: null,
        }).then(function (results) {
            var entry = results && results[curLayout];
            var html  = entry  && entry.html;
            if (html) {
                frame.srcdoc = buildSrcdoc(html);
                clearLoading('');
            } else {
                // Gracefully handle missing combinations (e.g. minimalist + glossy).
                frame.srcdoc = buildSrcdoc(
                    '<div style="display:flex;height:100vh;align-items:center;' +
                    'justify-content:center;font-family:system-ui,sans-serif;color:#888;' +
                    'flex-direction:column;gap:8px;">' +
                    '<strong style="font-size:18px">Not available</strong>' +
                    '<span style="font-size:13px">' +
                    ' XML error OR ' +
                    curLayout + ' &#xd7; ' + curVibe +
                    ' does not have a dedicated template.</span></div>'
                );
                clearLoading(curLayout + ' \u00d7 ' + curVibe + ' not available');
            }
        }).catch(function (e) {
            clearLoading('Error: ' + e.message);
        });
    }

    // ── Style change ───────────────────────────────────────────────────────────────
    // Compiles the SCSS palette server-side (same RPC as SelectStyle in the
    // configurator) then reloads the page so the new CSS bundle is picked up.
    // The selected style id is preserved in the URL so the dropdown stays in sync.
    function applyStyleChange(styleId) {
        setLoading('Compiling palette ' + styleId + '…');
        var tokens = readStyleTokens(styleId);
        // Build the SCSS payload.  Mirrors buildStyleScssValues() in
        // configurator.js — must include 'google-fonts' so o-get-font-info()
        // can resolve the chosen typefaces and 'display-N-line-height: 1' for
        // the heading baseline.
        var scssValues = {
            'color-palettes-name' : "'" + styleId + "'",
            'headings-font'       : "'" + tokens.fontHead + "'",
            'font'                : "'" + tokens.fontBody + "'",
            'btn-border-radius'   : tokens.radius,
            'google-fonts'        : "('" + tokens.fontHead + "', '" + tokens.fontBody + "')",
        };
        for (var n = 1; n <= 6; n++) {
            scssValues['display-' + n + '-line-height'] = '1';
        }
        jsonRpc('/web/dataset/call_kw', {
            model  : 'website.assets',
            method : 'make_scss_customization',
            args   : [
                '/website/static/src/scss/options/user_values.scss',
                scssValues,
            ],
            kwargs : {},
        }).then(function () {
            // Reload the page after SCSS compilation so the new CSS bundle is served.
            var params = new URLSearchParams(location.search);
            params.set('style',  styleId);
            params.set('vibe',   curVibe);
            params.set('layout', curLayout);
            location.search = params.toString();
        }).catch(function (e) {
            clearLoading('Style error: ' + e.message);
        });
    }

    // ── Update URL without reloading (for vibe / layout changes) ──────────────────
    function updateUrl(extraParams) {
        var params = new URLSearchParams(location.search);
        Object.keys(extraParams).forEach(function (k) { params.set(k, extraParams[k]); });
        history.replaceState(null, '', '?' + params.toString());
    }

    // ── Event listeners ───────────────────────────────────────────────────────────
    styleCtrl.addEventListener('change', function () {
        var v = styleCtrl.value;
        if (v) { applyStyleChange(v); }
    });

    vibeCtrl.addEventListener('change', function () {
        curVibe = vibeCtrl.value;
        updateUrl({ vibe: curVibe });
        loadPreview();
    });

    layoutCtrl.addEventListener('change', function () {
        curLayout = layoutCtrl.value;
        updateUrl({ layout: curLayout });
        loadPreview();
    });

    // ── Initial load ─────────────────────────────────────────────────────────────
    loadPreview();

}());
//
